INSERT INTO `ws_faq` (`id`, `type`, `question`, `answer`, `is_expand`, `created_at`, `updated_at`) VALUES
(1, 'general', 'એપ્લિકેશનમાં કોર્સ કઈ રીતે ખરીદી શકાય?\n', 'તમે એપ્લિકેશન માંથી જે કોર્સે ખરીદવો હોય એ ઓપન કરી અને ત્યાંથી પેમેન્ટ કરી ને કોર્સ ખરીદી કરી શકો .', 0, '2023-02-10 17:35:43', '2023-02-10 17:35:43'),
(2, 'general', 'શું તમે Login Details Change કરી શકશો ?', 'જેટલા સમય માટે તમે App Buy કરો છો તેટલા સમય સુધી તમે Login Details Change કરી શકશો નહિ.', 0, '2023-02-10 17:35:43', '2023-02-10 17:35:43'),
(5, 'referral', 'How does the referral program work?', 'The referral program is a way for you to earn rewards by referring websankul app to your friends. When you refer someone, they will receive a unique code. If they use that code to buy any package or course, you will earn a reward.', 0, '2023-02-10 17:35:43', '2023-02-10 17:35:43'),
(6, 'general', 'શું તમે Login Details Change કરી શકશો ?', 'જેટલા સમય માટે તમે App Buy કરો છો તેટલા સમય સુધી તમે Login Details Change કરી શકશો નહિ.', 0, '2023-02-10 17:35:43', '2023-02-10 17:35:43'),
(7, 'general', 'એપ્લિકેશનમાં કઈ રીતે ખરીદી શકાય?\n', 'તમે એપ્લિકેશન માંથી જે કોર્સે ખરીદવો હોય એ ઓપન કરી અને ત્યાંથી પેમેન્ટ કરી ને કોર્સ ખરીદી કરી શકો .', 0, '2023-02-10 17:35:43', '2023-02-10 17:35:43'),
(8, 'general', 'શું તમે Login Details Change કરી શકશો ?', 'જેટલા સમય માટે તમે App Buy કરો છો તેટલા સમય સુધી તમે Login Details Change કરી શકશો નહિ.', 0, '2023-02-10 17:35:43', '2023-02-10 17:35:43'),
(9, 'referral', 'Is there any limit to the number of friends I can refer?', 'There is no limit to the number of students you can refer.', 0, '2023-02-10 17:35:43', '2023-02-10 17:35:43'),
(10, 'referral', 'What rewards I can get for referral?', 'You will earn 10% of the purchase amount of each friend who uses your code to purchase websankul package or course.', 0, '2023-02-10 17:35:43', '2023-02-10 17:35:43'),
(11, 'referral', 'Is there any limit to transfer the wallet balance into my bank account?', 'Yes, you need a minimum of 500 rupees in your wallet to transfer into your bank account.', 0, '2023-02-10 17:35:43', '2023-02-10 17:35:43'),
(12, 'referral', 'How do I share my referral  code?', 'You can share your referral code on social-media i.e whatsapp, facebook, Instagram, Telegram etc. or via e-mail or any other medium you like.', 0, '2023-02-10 17:35:43', '2023-02-10 17:35:43'),
(13, 'referral', 'What is the validity of wallet balance?', 'In the absence of any activity for 90 consecutive days, the referral rewards will automatically expire.', 0, '2023-02-10 17:35:43', '2023-02-10 17:35:43'),
(14, 'referral', 'What If I entered the wrong bank details?', 'You will not get any rewards in your bank and Websankul will be not responsible for any issue.', 0, '2023-02-10 17:35:43', '2023-02-10 17:35:43'),
(15, 'referral', 'Can I use rewards money in app?', 'Yes, you can use rewards to purchase package and course. But you can not use reward to buy e-books, books and pendrive course', 0, '2023-02-10 17:35:43', '2023-02-10 17:35:43');
