INSERT INTO `ws_package` (`id`, `name`, `description`, `image`, `shareable_link`, `with_material`, `without_material`, `pc_material_id`, `status`, `package_type_id`, `educator_id`, `exam_id`, `order_by`, `created_at`, `updated_at`) VALUES
(3, 'CCE', '<h2 style=\"font-size:20px;color:#ff7289\"><b>Description</b></h2>\r\n<ul style=\"top:-4px\">\r\n    <li>ક્લાસની 3 ની નવી પરીક્ષા પદ્ધતિની તમામ પરીક્ષાઓ માટે ઉપયોગી.</li><li>તમામ વિષયોની ઝીણવટભરી અને પરીક્ષાલક્ષી માહિતી આપતા ઉચ્ચ ગુણવત્તાના વિડિયો.\r\n    </li><li>અભ્યાસક્રમ મુજબ દરેક વિષયની જે- તે વિષયના એક થી વધુ નિષ્ણાંત શિક્ષકો (ફેકલ્ટી) દ્વારા પરીક્ષાલક્ષી સમજ.\r\n    </li><li>English, ગુજરાતી, ગણિત, રિઝનીંગ વગેરે જેવા તમામ વિષયોને આવરી લેતો કોર્સ.\r\n    </li><li>દરેક વિષયનું મટીરિયલ PDF સ્વરૂપે FREE\r\n    <div><strong><u>વિશેષ</u></strong></div>\r\n    </li><li><b style=\"color:#ff7289\">3000+ </b>HD Video</li>\r\n    <li><b style=\"color:#ff7289\">35+ </b>Expert Faculties</li>\r\n    <li><b style=\"color:#ff7289\">30+ </b>Subjects Covered</li>\r\n    <li><b>TOPIC</b> Wise Test</li><br>\r\n    <li><b style=\"color:#00000\">Note : </b>Without Material કોર્સમાં કોઈપણ મટીરિયલ મળવા પાત્ર નથી.</li>\r\n<li><b style=\"color:#00000\">Note : </b>With Material કોર્સમાં નીચેની બુક + મટીરિયલ મળવા પાત્ર રહેશે.</li>\r\n<div><strong><u>Books &amp; Materials</u></strong></div>\r\n<li>CCE 50 Paperset</li><li>Maths</li><li>Reasoning (New)</li><li>Gujarati Grammar (Material)</li><li>English Grammar (Material)</li><li>Shabdvaibhav</li><li>Golden MCQ&nbsp; - English Grammar</li><li>NCERT સાર ઈતિહાસ</li><li>NCERT સાર ભૂગોળ</li><li>NCERT સાર Culture</li><li>GCERT સાર સામાજિક વિજ્ઞાન</li><li>Gujarati Language - Mains</li><li>English Language - Mains</li><li>History- Mains</li><li>Culture- Mains</li><li>Polity- Mains</li><li>Public Administration- Mains</li><li>Economy- Mains</li><li>Geography And Science - Mains</li><li>2 Months Current Affair(2 Book)</li></ul><ul style=\"top:-4px\"><li style=\"font-weight: bold;\"><span style=\"font-weight: bolder;\">દરેક With Material કોર્ષ કે પેકેજની કિંમતમાં કુરિયર ચાર્જ,પેકેજિંગ ચાર્જ , Labour Cost અને Logistic Cost નો સમાવેશ થયેલ છે કોઈ અલગથી ચાર્જ આપવાનો રહેશે નહિ.<br></span></li><li style=\"\"><b>ગુજરાત બહારનું&nbsp; એડ્રેસ હશે તો કુરિયર ચાર્જ અલગથી આપવાનો રહેશે .</b></li></ul>', 'cce_pre_mains_new_thu.webp', 'https://gpsconline.page.link/generalpackage', '17 Books\\n2 Material\\n2 Months Current Affair(2 Book)\\nTotal = 21 ( Books + Materials + Magazine )', 'Affordable Education', NULL, 1, 1, NULL, 1, 11, '2020-07-12 12:49:44', '2026-01-01 12:52:08'),
(88, 'DySO I STI I GPSC', '<h2 style=\"font-size:20px;color:#ff7289\"><b>Description</b></h2> <ul style=\"top:-4px\">      <li>ગુજરાતની સર્વશ્રેષ્ઠ ફેકલ્ટીઝ દ્વારા દરેક વિષયના \r\n     ઉંડાણપૂર્વક અને સરળ સમજૂતી સાથેના લેકચર્સ</li><li>પ્રિલીમ્સ અને મુખ્ય પરીક્ષાના સમગ્ર અભ્યાસક્રમનો\r\n     સમાવેશ</li><li>20 વિષયોના 4200થી વધુ HD વીડિયો \r\n     લેકચર્સનો સમાવેશ</li><li>સ્વમૂલ્યાંકન માટે 1000થી વધુ ટેસ્ટ (ટોપિક વાઈઝ)</li><li>50+ Test Papers (4000+ Questions)</li><li>NCERT Material in Gujarati (History + Geography)</li><li>Prelims + Mains Material (Mind Carvings, PT Special, Mindmaps)<br><br></li></ul>', 'dyso_sti_gpsc_ele_ej.webp', 'https://', 'Affordable  Education', 'Affordable  Education', NULL, 1, 1, NULL, 1, -8, '2023-07-27 14:46:06', '2025-06-27 10:21:31'),
(89, 'GSRTC Conductor', '<h2 style=\"font-size:20px;color:#ff7289\"><b>Description</b></h2> <ul style=\"top:-4px\">      <li>નવા સિલેબસ મુજબ તૈયાર કરેલ રેકોર્ડડ સ્માર્ટ કોર્સ.</li><li>ગુજરાતની અનુભવી ફેકલ્ટી દ્વારા તૈયાર થયેલ કોર્સ.</li><li>રોડ સેફટીના અલગ વીડિયો.</li><li>નિગમને લગતી તમામ માહિતી.</li><li>ટિકિટ અને લગેજને ભાડાના ગાણિતિક પ્રશ્નોની સરળ સમજૂતી.</li><li>મોટર વ્હીકલ એક્ટ બાબતે સંપૂર્ણ ડિટેલમાં ચર્ચા.</li><li>કંડક્ટરની ફરજો માટે અલગથી રેકોર્ડડ વીડિયો.</li><li>GK, કરંટ અફેર્સ, Maths, ગુજરાતી વ્યાકરણ, અંગ્રેજી વ્યાકરણ તમામ વિષયોનો સમાવેશ.<br><br></li></ul>\r\n\r\n<h2 style=\"font-size:20px;color:#ff7289\"><b>Terms &amp; Conditions</b></h2> <ul style=\"top:-4px\"><li>GSRTC કંડકટર Lecture ની PDF મળવાપાત્ર રહેશે નહીં.</li></ul>', 'gsrtc_conductor_ele.webp', 'https://', 'Affordable  Education', 'Affordable  Education', NULL, 1, 1, NULL, 21, 14, '2023-08-14 17:36:32', '2025-01-01 11:24:38'),
