INSERT INTO `ws_termsandcondition` (`id`, `module`, `terms`, `freeShippingMinimumOrderAmount`, `status`) VALUES
(1, 'book', 'તમે ઓર્ડર કરાવેલી બુક 3 થી 5 કામકાજ ના દિવસ માં તમારા આપેલા સરનામાં પર મળવા પાત્ર રહેશે.\\nજો અનાવશ્યક સંજોગો માં પુસ્તક મળવામાં વિલંબ થાય તો સહકાર આપવા વિનંતી. \\nઆપણી કુરિયર સેવા દ્વારા ગામડાંના વિસ્તારમાં પુસ્તક પહોંચી શકશે નહિ. \\nજો તમે ગામડામાં રહો છો તો તમારે તમારી નજીકના તાલુકાનું કોઈ પણ સરનામું લખવું અથવા તમારે તાલુકાની તિરુપતિ કુરિયર સર્વિસની ઓફિસ પરથી કુરિયર મેળવી લેવાનું રહેશે. \\nઓનલાઈન ઓર્ડર કર્યા બાદ કોઈ પણ સંજોગોમાં ઓર્ડર કેન્સલ થશે નહિ. \\nએક વાર payment successful થયા પછી refund મળી શકશે નહિ .\\nગુજરાત ની બહાર બુક મેળવા માટે વધારાનો ચાર્જ આપવાનો રહેશે. \\nજો પુસ્તક ખામી યુક્ત અથવા મંગાવેલ પુસ્તક ના સ્થાને અન્ય કોઈ પુસ્તક મળે તો 3 દિવસ માં પાછા મોકલાવી દેવું ત્યાર બાદ સંસ્થા ની જવાબદારી રહેશે નહિ.\\n book helpline number : +91 77779 91348', 500, 1),
(2, 'pendrive', ' વેબસંકુલ પેનડ્રાઈવ કોર્સ એક જ  ડિવાઇઝ સાથે રજીસ્ટર થઈ શકશે.\\n કોઈ પણ સંજોગોમાં લેપટોપ,કોમ્પ્યુટર ખરાબ થઈ જશે તો પેનડ્રાઇવ અન્ય ડિવાઇઝમાં  બદલી શકાશે નહીં.\\n ઓપરેટિંગ સિસ્ટમ અપડેટ, System Format, System Crash બાદ ફરીથી રજીસ્ટ્રેશન થઈ શકશે નહીં.\\n કોઈ પણ કારણોસર ડિવાઇઝ બદલાવવાની જરૂર પડે છે તો Device Transfer Charge – 1000/- અલગથી ચુકવવાના રહેશે.\\n એક વખત ઓર્ડર કર્યા બાદ GPSC કોર્સમાંથી Class – 3 કે Class – 3 કોર્સમાંથી GPSC ના કોર્સમાં બદલી શકાશે નહીં.\\n એક વાર પેનડ્રાઈવ ઓર્ડર થયા બાદ ભવિષ્યમાં તેમાં રહેલા વિડિયો લેકચર કે મટીરિયલમાં નવો ઉમેરો કે અપડેટ થશે નહીં.\\n આપને મળેલ પેનડ્રાઈવ સાચવવાની જવાબદારી તમારી પોતાની રહેશે, જો તે ખોવાઈ જાય, તૂટી જાય કે કોઈ અન્ય કારણોસર બગડી જાય તો તેની જવાબદારી સંસ્થાની રહેશે નહીં.\\n પેનડ્રાઇવ Android TV, Projector, Large Display કે અન્ય ક્લોનીંગ ડિવાઇઝમાં ચાલશે નહીં .\\n પેનડ્રાઈવને Android ટીવી, Projector, Screen Sharing, Mirror Casting, Screen Recording, Application Cloning કે અન્ય કોઈ પણ રીતે છેડછાડ કરવી એ ફોજદારી ગુનો બને છે અને સંસ્થાના ધ્યાને આવતા કાયદેસરની કાર્યવાહી કરવામાં આવશે.', 0, 1),
(3, 'referral code', '\"[\\n  {\\n    \\\"title\\\": \\\"By participating in the referral program, you agree to these terms and conditions:\\\"\\n  },\\n  {\\n    \\\"title\\\": \\\"Eligibility\\\",\\n    \\\"description\\\": \\\"The referral program is open to all registered users of Websankul.\\\"\\n  },\\n  {\\n    \\\"title\\\": \\\"Limitations\\\",\\n    \\\"description\\\": \\\"Websankul may suspend or terminate the Refer and Earn program or the users ability to participate in the program at any time for any reason.\\\\\\\\nIn the absence of any activity for 90 consecutive days, the referral rewards will automatically expire.\\\\\\\\nYou can use maximum upto 50% of the payable amount from your wallet for the purchase of any courses or packages.\\\\\\\\nWebsankul has rights to change the promocode discount percentage and referral rewards percentage at any time.\\\\\\\\nyou can not use your promocode for self-purchase.\\\\\\\\nPromocode is not applicable on e-books,pendrive courses and books.\\\\\\\\nRewarded money cannot be used for the purchase of e-books, physical books or pendrive courses.\\\\\\\\nOnce your promocode is generated, you will not regenerated or change your promocode ever.\\\"\\n  },\\n{\\n    \\\"title\\\": \\\"Bank Account\\\",\\n    \\\"description\\\": \\\"Check your bank details properly before requesting the bank transfer. If the bank account details are wrong, then Websankul will not be responsible for any kind of issue during the bank transfer.\\\\\\\\nYou can not transfer your wallet Amount into wallet of other users.\\\\\\\\nYou can not add money directly into your wallet amount.\\\\\\\\nYou must have a minimum amount of 500 rupees to transfer into your bank acccount.\\\"\\n  },\\n  {\\n    \\\"title\\\": \\\"General Terms\\\",\\n    \\\"description\\\": \\\"Websankul reserves the rights to modify or terminate the referral program at any time.\\\\\\\\nWebsankul is not responsible for any technical or other problems that may prevent you